/* ============================================================================
   iSMART — Trợ lý ISAAC · Logic
   Chatbot trả lời thật bằng AI (window.claude.complete), grounded vào
   Nội quy lao động + Quy chế lương thưởng (window.ISMART_KB).
   ============================================================================ */
(function () {
  const KB = window.ISMART_KB;
  const MASCOT = 'data:image/png;base64,';
  const STORE_KEY = 'ismart-robo-chat-v1';

  /* ── Icons (inline SVG, stroke currentColor) ──────────────────────────── */
  const I = {
    clock: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
    palmtree: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M13 8c0-2.76-2.46-5-5.5-5S2 5.24 2 8h2.5"/><path d="M13 7.14A5.82 5.82 0 0 1 16.5 6c2.76 0 5 1.79 5 4h-3"/><path d="M5.89 9.71c-2.15 1.36-3.27 3.84-2.89 6.29 1.81-.49 3.32-1.74 4.18-3.39"/><path d="M13 8c0 2.21 1.5 4 3.5 4 .5 0 1-.1 1.5-.31"/><path d="M13 7.14c-.34 5.16-1.65 9.86-2 12.86"/><path d="M9 22h6"/></svg>',
    wallet: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 7V5a1 1 0 0 0-1-1H4a2 2 0 0 0 0 4h16a1 1 0 0 1 1 1v3m0 0v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V8"/><circle cx="16.5" cy="13" r="1.2" fill="currentColor" stroke="none"/></svg>',
    gift: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="8" width="18" height="4" rx="1"/><path d="M12 8v13M5 12v7a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-7"/><path d="M12 8S10.5 3 8 4.5 9.5 8 12 8zM12 8s1.5-5 4-3.5S14.5 8 12 8z"/></svg>',
    'file-signature': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v9"/><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M19 8v3"/><path d="M3 21s1-3 4.5-3c2 0 2.5 1.5 4.5 1.5S15 18 16 18"/></svg>',
    gavel: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m14 13-7.5 7.5a2.12 2.12 0 0 1-3-3L11 10"/><path d="m16 16 6-6"/><path d="m8 8 6-6"/><path d="m9 7 8 8"/><path d="m21 11-8-8"/><path d="M3 21h9"/></svg>',
    headset: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 14v-2a8 8 0 0 1 16 0v2"/><path d="M18 19a2 2 0 0 1-2 2h-2"/><rect x="2" y="14" width="4" height="6" rx="1"/><rect x="18" y="14" width="4" height="6" rx="1"/></svg>',
    phone: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/></svg>',
    mail: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 7 10 6 10-6"/></svg>',
    book: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>',
    refresh: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 0 1 15-6.7L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-15 6.7L3 16"/><path d="M3 21v-5h5"/></svg>',
    send: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.536 21.686a.5.5 0 0 0 .937-.024l6.5-19a.496.496 0 0 0-.635-.635l-19 6.5a.5.5 0 0 0-.024.937l7.93 3.18a2 2 0 0 1 1.112 1.11z"/><path d="m21.854 2.147-10.94 10.939"/></svg>',
    user: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></svg>',
    menu: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M4 6h16M4 12h16M4 18h16"/></svg>',
    spark: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v3m0 12v3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1M3 12h3m12 0h3M5.6 18.4l2.1-2.1m8.6-8.6 2.1-2.1"/></svg>'
  };

  /* ── DOM refs ─────────────────────────────────────────────────────────── */
  const app = document.getElementById('app');
  const sideScroll = document.getElementById('sideScroll');
  const stream = document.getElementById('stream');
  const streamInner = document.getElementById('streamInner');
  const ta = document.getElementById('ta');
  const sendBtn = document.getElementById('send');

  /* ── State ────────────────────────────────────────────────────────────── */
  let messages = [];   // {role:'user'|'assistant', content, sources?, fallback?}
  let busy = false;

  /* ── Build sidebar topics ─────────────────────────────────────────────── */
  KB.TOPICS.forEach((t) => {
    const b = document.createElement('button');
    b.className = 'topic';
    b.dataset.topic = t.id;
    b.innerHTML = `<span class="topic-ic c-${t.color}">${I[t.icon] || ''}</span><span class="topic-lbl">${t.label}</span>`;
    b.addEventListener('click', () => {
      document.querySelectorAll('.topic').forEach((x) => x.classList.remove('active'));
      b.classList.add('active');
      renderTopicChips(t);
      app.classList.remove('nav-open');
    });
    sideScroll.appendChild(b);
  });

  /* ── Welcome screen ───────────────────────────────────────────────────── */
  function renderWelcome() {
    const starter = [
      { ic: 'clock', q: 'Giờ làm việc và thời gian thử việc quy định thế nào?' },
      { ic: 'wallet', q: 'Tiền lương tháng được tính theo công thức nào?' },
      { ic: 'palmtree', q: 'Tôi được bao nhiêu ngày phép năm?' },
      { ic: 'gift', q: 'Thưởng thâm niên và phúc lợi gồm những gì?' }
    ];
    streamInner.innerHTML = `
      <div class="welcome">
        <div class="welcome-ava"><img src="${MASCOT}" alt="ISAAC"></div>
        <h1>Xin chào, tôi là <em>ISAAC</em> 👋</h1>
        <p>Trợ lý ảo của iSMART. Tôi có thể giải đáp mọi thắc mắc của bạn về
        <b>Nội quy lao động</b> và <b>Quy chế lương thưởng</b> của Công ty.</p>
      </div>
      <div class="qhint">Hỏi thử một câu</div>
      <div class="chips" id="welcomeChips"></div>`;
    const wrap = streamInner.querySelector('#welcomeChips');
    starter.forEach((s) => wrap.appendChild(makeChip(s.q, s.ic)));
  }

  function makeChip(q, icon) {
    const c = document.createElement('button');
    c.className = 'chip';
    c.innerHTML = `${I[icon] || I.spark}<span>${q}</span>`;
    c.addEventListener('click', () => { if (!busy) ask(q); });
    return c;
  }

  /* ── Topic chip panel (replaces welcome when a topic picked & no msgs) ── */
  function renderTopicChips(topic) {
    if (messages.length) return; // don't disturb an active conversation
    streamInner.innerHTML = `
      <div class="welcome">
        <div class="welcome-ava"><img src="${MASCOT}" alt="ISAAC"></div>
        <h1 style="font-size:24px">${topic.label}</h1>
        <p>Chọn một câu hỏi bên dưới, hoặc gõ câu hỏi của riêng bạn.</p>
      </div>
      <div class="qhint">Câu hỏi thường gặp</div>
      <div class="chips" id="topicChips"></div>`;
    const wrap = streamInner.querySelector('#topicChips');
    topic.questions.forEach((q) => wrap.appendChild(makeChip(q, topic.icon)));
  }

  /* ── Render full message stream ───────────────────────────────────────── */
  function renderMessages() {
    streamInner.innerHTML = '';
    messages.forEach((m, idx) => streamInner.appendChild(renderMsg(m, idx)));
  }

  function renderMsg(m, idx) {
    const row = document.createElement('div');
    row.className = 'msg ' + (m.role === 'user' ? 'user' : 'bot');

    const ava = document.createElement('div');
    ava.className = 'msg-ava';
    ava.innerHTML = m.role === 'user' ? I.user : `<img src="${MASCOT}" alt="ISAAC">`;

    const col = document.createElement('div');
    col.style.minWidth = '0';
    col.style.maxWidth = 'calc(100% - 48px)';

    const bubble = document.createElement('div');
    bubble.className = 'bubble';
    bubble.innerHTML = m.role === 'user' ? escapeHtml(m.content) : mdToHtml(m.content);

    // sources
    if (m.role === 'assistant' && m.sources && m.sources.length) {
      const src = document.createElement('div');
      src.className = 'src';
      src.innerHTML = `<span class="src-lbl">${I.book}Nguồn</span>` +
        m.sources.map((s) => `<span class="src-pill">${escapeHtml(s)}</span>`).join('');
      bubble.appendChild(src);
    }
    col.appendChild(bubble);

    // HR fallback row
    if (m.role === 'assistant' && m.fallback) {
      const af = document.createElement('div');
      af.className = 'aftermsg';
      af.innerHTML = `<span>Cần hỗ trợ thêm?</span>
        <button data-act="hr">${I.headset} Liên hệ Phòng Nhân sự & Văn hóa</button>`;
      af.querySelector('button').addEventListener('click', showHR);
      col.appendChild(af);
    }

    row.appendChild(ava);
    row.appendChild(col);
    return row;
  }

  function renderTyping() {
    const row = document.createElement('div');
    row.className = 'msg bot';
    row.id = 'typingRow';
    row.innerHTML = `<div class="msg-ava"><img src="${MASCOT}" alt="ISAAC"></div>
      <div class="bubble"><div class="typing"><span></span><span></span><span></span></div></div>`;
    streamInner.appendChild(row);
    scrollDown();
  }
  function removeTyping() { const r = document.getElementById('typingRow'); if (r) r.remove(); }

  function scrollDown() { requestAnimationFrame(() => { stream.scrollTop = stream.scrollHeight; }); }

  /* ── Ask flow ─────────────────────────────────────────────────────────── */
  async function ask(text) {
    text = (text || '').trim();
    if (!text || busy) return;
    busy = true; sendBtn.disabled = true;

    messages.push({ role: 'user', content: text });
    renderMessages();
    scrollDown();
    ta.value = ''; autoGrow();
    renderTyping();

    let raw = '';
    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-app-email': sessionStorage.getItem('ismart-robo-email') || ''
        },
        body: JSON.stringify({ prompt: buildPrompt(text) })
      });
      if (res.status === 401) {
        // email không hợp lệ / hết phiên — quay lại màn đăng nhập
        sessionStorage.removeItem('ismart-robo-email');
        removeTyping();
        location.reload();
        return;
      }
      const data = await res.json();
      raw = data.text || JSON.stringify({ answer: '', found: false });
    } catch (e) {
      raw = JSON.stringify({ answer: '', found: false });
    }
    removeTyping();

    const parsed = parseReply(raw);
    messages.push({
      role: 'assistant',
      content: parsed.answer,
      sources: parsed.sources,
      fallback: !parsed.found
    });
    save();
    renderMessages();
    scrollDown();
    busy = false; sendBtn.disabled = false;
    ta.focus();
  }

  /* ── Prompt construction ──────────────────────────────────────────────── */
  function buildPrompt(question) {
    const history = messages.slice(-7, -1)
      .map((m) => (m.role === 'user' ? 'NGƯỜI LAO ĐỘNG' : 'ISAAC') + ': ' + m.content)
      .join('\n');

    return `Bạn là "ISAAC" — trợ lý nhân sự ảo của Công ty Cổ phần Giáo dục iSMART.
Nhiệm vụ: trả lời câu hỏi của NGƯỜI LAO ĐỘNG về NỘI QUY LAO ĐỘNG và QUY CHẾ LƯƠNG THƯỞNG,
CHỈ dựa trên hai tài liệu nội bộ được cung cấp dưới đây. KHÔNG bịa đặt, KHÔNG suy diễn ngoài tài liệu.

QUY TẮC:
- Trả lời bằng tiếng Việt, có dấu đầy đủ, giọng thân thiện, chuyên nghiệp, ngắn gọn, dễ hiểu.
- Xưng "ISAAC", gọi người hỏi là "bạn".
- Dùng số liệu CHÍNH XÁC từ tài liệu (số ngày, %, số tiền, công thức...). Khi hữu ích, trình bày dạng gạch đầu dòng.
- Nếu câu hỏi liên quan đến mức lương/thu nhập CỤ THỂ của cá nhân, hãy nêu nguyên tắc chung và lưu ý rằng thông tin lương là BẢO MẬT (Điều 6 Quy chế lương thưởng), đề nghị liên hệ Phòng Nhân sự.
- Nếu thông tin KHÔNG có trong tài liệu, đặt "found": false và lịch sự nói rằng bạn chưa có thông tin, sẽ chuyển tới Phòng Nhân sự.
- "sources": liệt kê tối đa 2 nhãn nguồn ngắn gọn, ví dụ ["Nội quy LĐ – Chương I", "Quy chế lương – Điều 8"].

ĐỊNH DẠNG ĐẦU RA — chỉ trả về MỘT object JSON hợp lệ, không kèm văn bản nào khác:
{"answer":"...(có thể dùng \\n và - để xuống dòng/gạch đầu dòng, **đậm** cho số liệu quan trọng)...","sources":["..."],"found":true}

================= TÀI LIỆU 1: NỘI QUY LAO ĐỘNG =================
${KB.REGULATION_TEXT}

================= TÀI LIỆU 2: QUY CHẾ LƯƠNG THƯỞNG =================
${KB.SALARY_POLICY || '(Chưa có dữ liệu — nếu câu hỏi thuộc nhóm này, đặt found:false.)'}

================= LIÊN HỆ =================
Email ${KB.CONTACT.email} · ${KB.CONTACT.hr_note}

${history ? '================= NGỮ CẢNH HỘI THOẠI =================\n' + history + '\n' : ''}
================= CÂU HỎI =================
${question}

Trả về JSON ngay:`;
  }

  function parseReply(raw) {
    let obj = null;
    try {
      const a = raw.indexOf('{'); const b = raw.lastIndexOf('}');
      if (a !== -1 && b !== -1) obj = JSON.parse(raw.slice(a, b + 1));
    } catch (e) { /* fall through */ }
    if (!obj || typeof obj.answer !== 'string' || !obj.answer.trim()) {
      return {
        answer: 'Xin lỗi bạn, hiện ISAAC chưa tìm thấy thông tin phù hợp trong Nội quy lao động và Quy chế lương thưởng. Bạn vui lòng liên hệ Phòng Nhân sự để được hỗ trợ chính xác nhất nhé.',
        sources: [],
        found: false
      };
    }
    return {
      answer: obj.answer.trim(),
      sources: Array.isArray(obj.sources) ? obj.sources.slice(0, 2) : [],
      found: obj.found !== false
    };
  }

  /* ── HR fallback message ──────────────────────────────────────────────── */
  function showHR() {
    const c = KB.CONTACT;
    messages.push({
      role: 'assistant',
      content: `Bạn có thể liên hệ trực tiếp **${c.hr_note}** để được hỗ trợ:\n- ✉ Email: **${c.email}**\n\nISAAC luôn sẵn sàng nếu bạn còn câu hỏi nào khác về nội quy hay lương thưởng nhé!`,
      sources: []
    });
    save(); renderMessages(); scrollDown();
  }

  /* ── Markdown-lite → HTML ─────────────────────────────────────────────── */
  function mdToHtml(text) {
    const esc = escapeHtml(text);
    const lines = esc.split('\n');
    let html = ''; let inList = false;
    const inline = (s) => s
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/__(.+?)__/g, '<strong>$1</strong>');
    for (let ln of lines) {
      const t = ln.trim();
      if (/^[-•]\s+/.test(t)) {
        if (!inList) { html += '<ul>'; inList = true; }
        html += '<li>' + inline(t.replace(/^[-•]\s+/, '')) + '</li>';
      } else {
        if (inList) { html += '</ul>'; inList = false; }
        if (t) html += '<p>' + inline(t) + '</p>';
      }
    }
    if (inList) html += '</ul>';
    return html || '<p>' + inline(esc) + '</p>';
  }
  function escapeHtml(s) {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  /* ── Persistence ──────────────────────────────────────────────────────── */
  function save() { try { localStorage.setItem(STORE_KEY, JSON.stringify(messages)); } catch (e) {} }
  function load() {
    try { const r = localStorage.getItem(STORE_KEY); if (r) messages = JSON.parse(r) || []; } catch (e) { messages = []; }
  }
  function reset() {
    messages = []; save();
    document.querySelectorAll('.topic').forEach((x) => x.classList.remove('active'));
    renderWelcome();
  }

  /* ── Composer wiring ──────────────────────────────────────────────────── */
  function autoGrow() { ta.style.height = 'auto'; ta.style.height = Math.min(ta.scrollHeight, 120) + 'px'; }
  ta.addEventListener('input', autoGrow);
  ta.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ask(ta.value); }
  });
  sendBtn.addEventListener('click', () => ask(ta.value));
  document.getElementById('resetBtn').addEventListener('click', reset);
  document.getElementById('navToggle').addEventListener('click', () => app.classList.toggle('nav-open'));
  document.getElementById('scrim').addEventListener('click', () => app.classList.remove('nav-open'));

  // contact card in sidebar
  document.getElementById('hrCard').innerHTML =
    `<h4>${I.headset} ${KB.CONTACT.hr_note}</h4>
     <div class="hr-line">${I.mail}<a href="mailto:${KB.CONTACT.email}">${KB.CONTACT.email}</a></div>`;

  /* ── Init ─────────────────────────────────────────────────────────────── */
  load();
  if (messages.length) { renderMessages(); scrollDown(); } else { renderWelcome(); }
})();
